-- p9: Jonin quest lines (levels 30/40/50), new enemies, boss gear drops, level gates
alter table public.quest_lines add column if not exists min_level int not null default 0, add column if not exists boss_xp int, add column if not exists boss_ryo int;


-- level gate on quest lines
do $$ declare d text; begin
  d := pg_get_functiondef('public.start_quest(text)'::regprocedure);
  d := replace(d, '  if coalesce((c.quests->p_line->>''done'')::boolean, false) then',
'  if c.level < ql.min_level then raise exception ''Reach level % to take this quest.'', ql.min_level; end if;
  if coalesce((c.quests->p_line->>''done'')::boolean, false) then');
  if position('ql.min_level' in d) = 0 then raise exception 'start_quest patch failed'; end if;
  execute d;
end $$;

-- gear-reward bosses: XP and ryo from the quest line, a title for the first kill (drops are rolled for every boss already)
do $$ declare d text; begin
  d := pg_get_functiondef('public.raid_finish(uuid,boolean)'::regprocedure);
  d := replace(d, '    else v_xp := 1200; v_ryo := 1000;',
'    elsif ql.reward = ''gear'' then v_xp := coalesce(ql.boss_xp, 1500); v_ryo := coalesce(ql.boss_ryo, 1500);
      v_wins := coalesce((c.trophies->>r.line)::int, 0) + 1;
      v_title := case when v_wins = 1 then case r.line when ''mist'' then ''Mist Breaker'' when ''sands'' then ''Tomb Raider of the Sands'' when ''eclipse'' then ''Dawnbringer'' else null end else null end;
    else v_xp := 1200; v_ryo := 1000;');
  if position('boss_xp' in d) = 0 then raise exception 'raid_finish patch failed'; end if;
  execute d;
end $$;
